"""Run fresh R29 teacher probing and validated multi-label compilation."""

from __future__ import annotations
import argparse, gc, hashlib, json, random, time
from pathlib import Path
import torch

from experiments.autonomous_labeling_r27.public_qualification import _parse
from experiments.autonomous_labeling_r27.source_run import _control, _packages, _write_bundle
from experiments.factual_semantic_r16.public_qualification import _generate, _load_source, _render_chat
from experiments.foreign_capability_r14.core import R14Error, evidence_hash, sha256_file, write_json_once, write_jsonl_once
from .binding import load_config
from .facts import SYSTEM_PROMPT
from .isolation import run_isolated
from .protocol import answer_key, answer_packages, selected_facts


def run(config_path, reveal_path, output):
    root = Path(__file__).resolve().parents[2]
    if output.exists(): raise R14Error(f"immutable R29 output exists: {output}")
    config = load_config(root, config_path.resolve())
    if sha256_file(reveal_path) != config["reveal_sha256"]: raise R14Error("R29 reveal changed")
    reveal = json.loads(reveal_path.read_text(encoding="utf-8")); facts = selected_facts(reveal["secret_hex"], config["heldout_seed_commitment"], config["facts_per_domain"], config["excluded_fact_ids"]); output.mkdir(parents=True); tokenizer, model, snapshot = _load_source(config["source"]["model_id"], config["source"]["revision"]); torch.cuda.reset_peak_memory_stats(); started = time.perf_counter(); rows = []; bundle = []; tokens = 0; output_bytes = 0
    for fact in facts:
        for split, questions in (("extraction", fact.extraction_questions), ("evaluation", fact.evaluation_questions)):
            for view, question in enumerate(questions):
                rendered = _render_chat(tokenizer, SYSTEM_PROMPT, question); completion, count = _generate(tokenizer, model, rendered, config["source"]["max_new_tokens"])
                try: response, label = _parse(completion); parsed = True
                except (ValueError, json.JSONDecodeError): response, label, parsed = "", "", False
                row = {"split": split, "fact_id": fact.fact_id, "oracle_domain": fact.oracle_domain, "subject": fact.subject, "view": view, "question": question, "oracle_answer": fact.answer, "completion": completion, "parse_exact": parsed, "teacher_answer": response, "answer_exact": answer_key(response) == answer_key(fact.answer), "free_label": label, "label_syntax_valid": bool(label and label.isascii() and label.isalpha() and label.islower())}; rows.append(row)
                if split == "extraction": bundle.append({"subject": fact.subject, "question": question, "view": view, "answer": response, "label": label})
                tokens += count; output_bytes += len(completion.encode("utf-8"))
    del model, tokenizer; gc.collect(); torch.cuda.empty_cache(); random.Random(int(reveal["secret_hex"][:16], 16)).shuffle(bundle); rows_path = output / "source_rows.jsonl"; write_jsonl_once(rows_path, rows); bundle_path = output / "source_bundle.json"; _write_bundle(bundle_path, bundle); extraction = run_isolated(root, bundle_path, output / "extraction", config["physical_extraction"]["distribution"])
    control_rows, control_offset = _control(bundle); control_path = output / "control_bundle.json"; _write_bundle(control_path, control_rows); control = run_isolated(root, control_path, output / "control_extraction", config["physical_extraction"]["distribution"]); packages = _packages(output / "extraction", extraction["result"]); controls = _packages(output / "control_extraction", control["result"])
    validation = {row["subject_sha256"]: row for row in extraction["result"]["validation"]}; evaluation = []
    for row in (item for item in rows if item["split"] == "evaluation"):
        digest = hashlib.sha256(row["subject"].encode()).hexdigest(); validator_used = validation[digest]["validator_used"]; namespace = f"teacher/{row['oracle_domain']}"; selected = [item for item in packages if item["namespace"] == namespace]; tags = sorted(item["namespace"].split("/", 1)[1] for item in packages if any(fact["entity"] == row["subject"] for fact in item["facts"])); allowed = {row["oracle_domain"]}
        if row["oracle_domain"] == "mathematics": allowed.add("python")
        unauthorized = [item for item in packages if item["namespace"].split("/", 1)[1] not in allowed]
        evaluation.append({"fact_id": row["fact_id"], "oracle_domain": row["oracle_domain"], "subject": row["subject"], "view": row["view"], "question": row["question"], "namespace": namespace, "compiled_tags": tags, "allowed_tags": sorted(allowed), "validator_used": validator_used, "oracle_answer": row["oracle_answer"], "teacher_answer": row["teacher_answer"], "package_answer": answer_packages(selected, row["question"]), "unauthorized_answer": answer_packages(unauthorized, row["question"]), "control_answer": answer_packages([item for item in controls if item["namespace"] == namespace], row["question"])})
    evaluation_path = output / "evaluation.jsonl"; write_jsonl_once(evaluation_path, evaluation); source_eval_exact = sum(answer_key(row["teacher_answer"]) == answer_key(row["oracle_answer"]) for row in evaluation); package_exact = sum(answer_key(str(row["package_answer"] or "")) == answer_key(row["oracle_answer"]) for row in evaluation); validated_rows = [row for row in evaluation if row["validator_used"]]; unvalidated_rows = [row for row in evaluation if not row["validator_used"]]
    validator_by_subject = {row["subject_sha256"]: row["validator_used"] for row in extraction["result"]["validation"]}
    unvalidated_source_rows = [row for row in rows if not validator_by_subject[hashlib.sha256(row["subject"].encode()).hexdigest()]]
    validated_source_rows = [row for row in rows if validator_by_subject[hashlib.sha256(row["subject"].encode()).hexdigest()]]
    metrics = {"selected_facts": len(facts), "source_rows": len(rows), "parse_exact": sum(row["parse_exact"] for row in rows), "source_answer_exact": sum(row["answer_exact"] for row in rows), "unvalidated_source_rows": len(unvalidated_source_rows), "unvalidated_source_answer_exact": sum(row["answer_exact"] for row in unvalidated_source_rows), "validated_source_rows": len(validated_source_rows), "validated_source_answer_exact": sum(row["answer_exact"] for row in validated_source_rows), "label_syntax_valid": sum(row["label_syntax_valid"] for row in rows), "compiled_unique_facts": extraction["result"]["unique_facts"], "compiled_package_fact_records": extraction["result"]["package_fact_records"], "validator_uses": extraction["result"]["validator_uses"], "discovered_packages": len(packages), "oracle_domain_coverage": sum(row["oracle_domain"] in row["compiled_tags"] for row in evaluation), "tag_purity": sum(set(row["compiled_tags"]).issubset(set(row["allowed_tags"])) for row in evaluation), "package_oracle_exact": package_exact, "source_evaluation_oracle_exact": source_eval_exact, "package_teacher_agreement": sum(answer_key(str(row["package_answer"] or "")) == answer_key(row["teacher_answer"]) for row in evaluation), "unauthorized_packages_abstain": sum(row["unauthorized_answer"] is None for row in evaluation), "control_validated_exact": sum(answer_key(str(row["control_answer"] or "")) == answer_key(row["oracle_answer"]) for row in validated_rows), "control_unvalidated_exact": sum(answer_key(str(row["control_answer"] or "")) == answer_key(row["oracle_answer"]) for row in unvalidated_rows), "validated_evaluation_rows": len(validated_rows), "unvalidated_evaluation_rows": len(unvalidated_rows), "oracle_fields_consumed": extraction["result"]["oracle_fields_consumed"]}
    passed = metrics["selected_facts"] == 12 and metrics["source_rows"] == 72 and metrics["parse_exact"] >= 68 and metrics["unvalidated_source_rows"] == 36 and metrics["unvalidated_source_answer_exact"] >= 32 and metrics["label_syntax_valid"] >= 68 and metrics["compiled_unique_facts"] == 12 and metrics["compiled_package_fact_records"] >= 12 and metrics["validator_uses"] == 6 and metrics["discovered_packages"] >= 4 and metrics["oracle_domain_coverage"] == 36 and metrics["tag_purity"] == 36 and metrics["package_oracle_exact"] == 36 and metrics["package_oracle_exact"] >= metrics["source_evaluation_oracle_exact"] and metrics["unauthorized_packages_abstain"] == 36 and metrics["control_validated_exact"] == metrics["validated_evaluation_rows"] and metrics["control_unvalidated_exact"] <= 2 and metrics["oracle_fields_consumed"] == 0
    inventory = [{**item, "path": f"extraction/{item['path']}"} for item in extraction["result"]["packages"]]; result = {"format": "abi-r29-heldout-validated-source-result/1", "verdict": "PASS" if passed else "FAIL", "claim": "BOUNDED_VALIDATOR_BACKED_MULTILABEL_DISCOVERY_AND_COMPILATION", "claim_ceiling": "NOT_EXHAUSTIVE_DIAGNOSIS_OR_FLUENT_ENGLISH_EXTRACTION", "config_sha256": sha256_file(config_path), "reveal_sha256": sha256_file(reveal_path), "source": {"model_id": config["source"]["model_id"], "revision": config["source"]["revision"], "snapshot": str(snapshot), "training_steps": 0}, "metrics": metrics, "packages": inventory, "isolation": {"result_sha256": sha256_file(output / "extraction/result.json"), "launcher_sha256": sha256_file(output / "extraction/launcher.json"), "control_result_sha256": sha256_file(output / "control_extraction/result.json")}, "artifacts": {"source_rows": {"path": rows_path.name, "bytes": rows_path.stat().st_size, "sha256": sha256_file(rows_path)}, "source_bundle": {"path": bundle_path.name, "bytes": bundle_path.stat().st_size, "sha256": sha256_file(bundle_path)}, "evaluation": {"path": evaluation_path.name, "bytes": evaluation_path.stat().st_size, "sha256": sha256_file(evaluation_path)}}, "information_accounting": {"source_calls": len(rows), "generated_tokens": tokens, "output_bytes": output_bytes, "source_bundle_bytes": bundle_path.stat().st_size, "final_package_bytes": sum(item["bytes"] for item in inventory), "package_fact_records": metrics["compiled_package_fact_records"], "unique_facts": 12, "source_parameters_copied": 0, "bridge_parameters_trained": 0, "control_rotation_offset": control_offset, "elapsed_seconds": time.perf_counter() - started, "peak_gpu_memory_bytes": int(torch.cuda.max_memory_allocated())}, "full_abi_moonshot": "OPEN"}; result["evidence_sha256"] = evidence_hash(result); write_json_once(output / "result.json", result); return result
def main():
    parser = argparse.ArgumentParser(); parser.add_argument("--config", type=Path, required=True); parser.add_argument("--reveal", type=Path, required=True); parser.add_argument("--output", type=Path, required=True); args = parser.parse_args(); print(json.dumps(run(args.config, args.reveal, args.output), indent=2))
if __name__ == "__main__": main()
